{{ post.vorname }}<h2>Offizielle Clubadresse</h2>
<h3>{{ site.title }}</h3>
{% set group = attribute( site, 'club-einstellungen' ) %}
{{ group.official_address.official_address_text }}
<p>Telefon: 
 {% set group = attribute( site, 'club-einstellungen' ) %}
 <a href="tel:+49{{ group.official_address.telefon_url }}">
  +49 {{ group.official_address.telefon_nice }}
 </a>
</p>
<p>E-Mail: 
 {% set group = attribute( site, 'club-einstellungen' ) %}
 <a href="mailto:{{ group.official_address.email_adresse }}">
  {{ group.official_address.email_adresse }}
 </a>
</p>

<!-- Clubheim -->
<h3>Clubheim</h3>
{% set group = attribute( site, 'club-einstellungen' ) %}
{{ group.clubhouse.adresse_clubhouse }}
<p>Telefon: 
 {% set group = attribute( site, 'club-einstellungen' ) %}
 <a href="tel:+49{{ group.clubhouse.telefon_url }}">
  +49 {{ group.clubhouse.telefon_nice }}
 </a>
</p>

<!-- Vorstandsposition Query -->
{% set terms = ['jugendleiter', 'mitgliederverwaltung', 'spielausschuss'] %}

{% for term_slug in terms %}
 <h3>{{ term_slug | title }}</h3>
 
 {% set mit_board_role = mb.get_posts({
  post_type: 'mitglieder',
  tax_query: [
   {
    taxonomy: 'board_role',
    field: 'slug', 
    terms: term_slug
   }
  ]
 }) %}
 
 {% if mit_board_role %}
  {% for post in mit_board_role %}
   <p><strong>{{ post.vorname }} {{ post.nachname }}</strong></p>
   
   {% if post.board_address %}
    <p>{{ post.board_address }}</p>
   {% endif %}
   
   {% if post.board_email %}
    <p>E-Mail:
     <a href="mailto:{{ post.board_email }}">
      {{ post.board_email }}
     </a>
    </p>
   {% endif %}
   
   {% if post.board_phone %}
    <p>Telefon: {{ post.board_phone }}</p>
   {% endif %}
   
   {% if post.board_mobile %}
    <p>Mobil: {{ post.board_mobile }}</p>
   {% endif %}
  {% endfor %}
 {% else %}
  <p>Kein Mitglied gefunden für diese Position.</p>
 {% endif %}
{% endfor %}
